import {authClient} from './auth-client.js';
import {peerPayload,cleanAlias,appearance} from './garden-state.js';
// Only the authenticated server broker publishes visitor events. Clients are read-only subscribers.
export function createSanctuaryPresence({onPeers,onStatus,onCount}){
 let channel=null,joining=false,active=false,generation=0,lastSent=0,pending=null,heartbeat=null,expiry=null,ownSid=null,inflight=null,dirty=false,seq=0;
 const clientId=crypto.randomUUID(),peers=new Map(),sequences=new Map();let inbox=[],local={alias:'',x:50,y:77,...appearance(),pose:'idle'};
 function snapshot(){const now=Date.now();for(const [id,p]of peers)if(now-p.seen>35000)peers.delete(id);for(const [id,p]of sequences)if(now-p.time>70000)sequences.delete(id);onPeers([...peers.values()].map(p=>p.value).slice(0,16));onCount(active?peers.size+1:0);}
 async function emit(kind){const body={kind,client_id:clientId,seq:++seq,...(kind==='leave'?{}:local)};const {data,error}=await authClient().functions.invoke('lucky-sanctuary-event',{body});if(error||!data)throw new Error('connection unavailable');return data;}
 function receive(message){if(!message||!['join','update','leave'].includes(message.kind)||!Number.isSafeInteger(message.seq)||message.seq<0||message.seq>1000000000)return;if(!active){if(joining&&inbox.length<100)inbox.push(message);return;}const p=message.kind==='leave'?null:peerPayload(message.peer),id=message.kind==='leave'?message.sid:p?.sid;if(!id||id===ownSid)return;const previous=sequences.get(id)?.seq??-1;if(message.seq<=previous)return;sequences.set(id,{seq:message.seq,time:Date.now()});if(message.kind==='leave')peers.delete(id);else if(p)peers.set(id,{value:p,seen:Date.now()});snapshot();if(message.kind==='join')queuePublish();}
 async function leave(message='ออกจากลานร่วมแล้ว · ตอนนี้เป็นพื้นที่ส่วนตัว'){
  const wasConnected=active||joining;generation++;joining=false;active=false;clearTimeout(pending);clearInterval(heartbeat);clearInterval(expiry);pending=null;heartbeat=expiry=null;dirty=false;const old=channel,previous=inflight;channel=null;ownSid=null;peers.clear();sequences.clear();inbox=[];onPeers([]);onCount(0);onStatus(message,false);if(old)try{await authClient().removeChannel(old);}catch{}
  if(wasConnected){try{if(previous)await previous;await emit('leave');}catch{}}
 }
 function queuePublish(){dirty=true;if(!active||!channel||pending||inflight)return;const run=generation;pending=setTimeout(async()=>{pending=null;if(run!==generation||!active||document.hidden)return;dirty=false;lastSent=Date.now();try{inflight=emit('update');await inflight;}catch{if(run===generation)void leave('การเชื่อมต่อขัดข้อง · ลองเข้าร่วมใหม่ได้');}finally{inflight=null;if(dirty&&active)queuePublish();}},Math.max(0,900-(Date.now()-lastSent)));}
 async function join(alias,look){if(joining||active)return;const name=cleanAlias(alias);if(!name)throw new Error('กรุณาตั้งชื่อเล่นที่จะแสดงในลาน');if(document.hidden)throw new Error('กลับมายังหน้าลานก่อนเข้าร่วม');joining=true;const run=++generation;onStatus('กำลังเชื่อมต่อลานร่วม…',false);local={...local,...appearance(look),alias:name};
  try{await authClient().realtime.setAuth();if(run!==generation)return;if(document.hidden){await leave();return;}const current=authClient().channel('lucky-sanctuary-v320',{config:{private:true,broadcast:{self:false}}});channel=current;current.on('broadcast',{event:'visitor'},({payload})=>receive(payload));
   current.subscribe(async state=>{if(run!==generation)return;if(state==='SUBSCRIBED'){if(active){queuePublish();return;}if(document.hidden){await leave();return;}try{inflight=emit('join');const result=await inflight;inflight=null;if(run!==generation)return;const p=peerPayload(result.peer);if(!p)throw new Error();ownSid=p.sid;joining=false;active=true;lastSent=Date.now();onStatus('อยู่ในลานร่วม · ชื่อเล่นและตำแหน่งในลานจะแสดงให้สมาชิกที่เข้าร่วมเห็น',true);const queued=inbox;inbox=[];for(const m of queued)receive(m);snapshot();heartbeat=setInterval(queuePublish,10000);expiry=setInterval(snapshot,2000);}catch{inflight=null;if(run===generation)void leave('เข้าร่วมลานไม่สำเร็จ · ยังใช้พื้นที่ส่วนตัวได้ตามปกติ');}}else if(['CHANNEL_ERROR','TIMED_OUT','CLOSED'].includes(state))void leave('เชื่อมต่อลานร่วมไม่ได้ · ยังใช้กิจกรรมส่วนตัวได้ตามปกติ');});
  }catch{if(run===generation)await leave('เชื่อมต่อลานร่วมไม่ได้ กรุณาลองอีกครั้ง');}
 }
 function updatePosition(x,y,{pose='idle'}={}){const changed=local.x!==x||local.y!==y||local.pose!==pose;local={...local,x,y,pose};if(changed&&active)queuePublish();}
 function updateAppearance(look){local={...local,...appearance(look)};if(active)queuePublish();}
 const stop=()=>{void leave();};window.addEventListener('pagehide',stop);document.addEventListener('visibilitychange',()=>{if(document.hidden&&(active||joining))void leave('พักการเชื่อมต่อลานร่วมเมื่อออกจากหน้านี้ · กดเข้าร่วมใหม่ได้');});document.addEventListener('lucky-member-locked',stop);
 return {join,leave,updatePosition,updateAppearance,get active(){return active;},get joining(){return joining;}};
}
